/*---
description: toLowerCase of every code point U+A0000 through U+AFFFF matches Node by 4096-point block.
features: [ts-unicode-case-mapping, ts-strings, ts-unicode-exhaustive, ts-arrays, ts-tuples, ts-iteration, ts-numbers]
---*/
// Generated by tooling/unicode-cases/case-mapping.ts; Node 24.20.0 / Unicode 17.0 / ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Hash: FNV-1a, UTF-16 code units, offset 0x811c9dc5, prime 0x01000193.
// String.fromCodePoint keeps U+D800..U+DFFF as individual lone surrogate code units.
const blocks: [number, number][] = [
  [0xA0000, 0xD4B09C5],
  [0xA1000, 0xB21B19C5],
  [0xA2000, 0xE8A9E9C5],
  [0xA3000, 0x2F6301C5],
  [0xA4000, 0xD65991C5],
  [0xA5000, 0xC00719C5],
  [0xA6000, 0x7BF969C5],
  [0xA7000, 0x489BC9C5],
  [0xA8000, 0xCA4439C5],
  [0xA9000, 0xC85C91C5],
  [0xAA000, 0x358021C5],
  [0xAB000, 0x8F36D9C5],
  [0xAC000, 0xF5A631C5],
  [0xAD000, 0x5D3069C5],
  [0xAE000, 0x638C61C5],
  [0xAF000, 0xA90C51C5],
];
for (const [start, expected] of blocks) {
  let hash = 0x811c9dc5;
  for (let cp = start; cp < start + 4096; cp++) {
    const output = String.fromCodePoint(cp).toLowerCase();
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 0x01000193) >>> 0;
    }
  }
  assert.sameValue(hash, expected, "toLowerCase block U+" + start.toString(16) + "..U+" + (start + 4095).toString(16));
}
